import type { WeaponId } from '../weapons/ids.js';
import { restartAnim } from './restartAnim.js';

// ---- 右の操作一覧 ----
// 構えている武器の操作を並べる。最後に触ったのがパッドならパッドのボタンで出す
type ControlInput = 'attack' | 'aim' | 'reload' | 'wheel' | 'dash';
interface ControlBind { input: ControlInput; hold?: boolean }
// padKeys: パッドだけ押し方が違うとき
const WEAPON_CONTROLS: Record<WeaponId, { label: string; keys: ControlBind[]; padKeys?: ControlBind[] }[]> = {
  kunai: [
    { label: '投げる / 連射', keys: [{ input: 'attack' }] },
    { label: '呼び戻す（R またはホイール）', keys: [{ input: 'reload' }], padKeys: [{ input: 'reload' }] },
    { label: '刺さったクナイに照準でグラップル（押している間）', keys: [{ input: 'aim', hold: true }], padKeys: [{ input: 'aim', hold: true }] },
  ],
  handgun: [
    { label: '射撃', keys: [{ input: 'attack' }] },
    { label: 'リロード', keys: [{ input: 'reload' }] },
    { label: 'デッドアイ', keys: [{ input: 'aim' }] },
  ],
  sword: [
    { label: '斬る', keys: [{ input: 'attack' }] },
    { label: '溜め斬り', keys: [{ input: 'attack', hold: true }] },
    { label: '構え', keys: [{ input: 'aim' }] },
    { label: '一閃', keys: [{ input: 'aim' }, { input: 'attack' }] },
  ],
  sickle: [
    { label: '攻撃', keys: [{ input: 'attack' }] },
    { label: '鎖を投げる', keys: [{ input: 'aim' }, { input: 'attack' }] },
  ],
  axe: [
    { label: '攻撃', keys: [{ input: 'attack' }] },
    { label: '打ち上げ', keys: [{ input: 'attack', hold: true }] },
    { label: '突き飛ばし', keys: [{ input: 'wheel' }], padKeys: [{ input: 'dash' }, { input: 'aim' }] },
  ],
  bow: [
    { label: '引いて射る', keys: [{ input: 'attack', hold: true }] },
    { label: '跳弾矢', keys: [{ input: 'aim', hold: true }] },
    { label: '3 本射ち', keys: [{ input: 'wheel', hold: true }], padKeys: [{ input: 'dash' }, { input: 'aim', hold: true }] },
  ],
  bat: [
    { label: '攻撃', keys: [{ input: 'attack' }] },
    { label: 'チャージ攻撃', keys: [{ input: 'attack', hold: true }] },
  ],
  spear: [
    { label: '攻撃', keys: [{ input: 'attack' }] },
    { label: '回転薙ぎ', keys: [{ input: 'attack', hold: true }] },
    { label: '風車受け', keys: [{ input: 'aim', hold: true }] },
    { label: '突進突き', keys: [{ input: 'aim', hold: true }, { input: 'attack' }] },
    { label: '投げる / 呼び戻す', keys: [{ input: 'wheel' }], padKeys: [{ input: 'dash' }, { input: 'aim' }] },
  ],
  rifle: [
    { label: '撃つ', keys: [{ input: 'attack' }] },
    { label: 'スコープを覗く', keys: [{ input: 'aim', hold: true }] },
    { label: 'リロード（1 発ずつ）', keys: [{ input: 'reload' }] },
    { label: 'スピンコック乱射', keys: [{ input: 'wheel', hold: true }], padKeys: [{ input: 'dash' }, { input: 'aim', hold: true }] },
  ],
};
// マウス: 押すボタンの側を塗る
const mouseIcon = (side: 'left' | 'right') =>
  `<svg viewBox="0 0 20 28"><path class="f" d="${side === 'left' ? 'M10 1 V11 H1 V10 A9 9 0 0 1 10 1 Z' : 'M10 1 V11 H19 V10 A9 9 0 0 0 10 1 Z'}"/>` +
  `<rect class="o" x="1" y="1" width="18" height="26" rx="9"/><path class="o" d="M10 1 V11 M1 11 H19"/></svg>`;
// マウス: ホイールを塗る
const wheelIcon = () =>
  `<svg viewBox="0 0 20 28"><rect class="o" x="1" y="1" width="18" height="26" rx="9"/><path class="o" d="M10 1 V3.5 M10 9.5 V11 M1 11 H19"/>` +
  `<rect class="f" x="8" y="3.5" width="4" height="6" rx="2"/></svg>`;
const keyIcon = (label: string) =>
  `<svg viewBox="0 0 24 24"><rect class="o" x="1" y="1" width="22" height="22" rx="3"/><text class="t" x="12" y="12.5">${label}</text></svg>`;
// パッドのトリガー: 肩の形の枠に名前
const triggerIcon = (label: string) =>
  `<svg viewBox="0 0 30 24"><path class="o" d="M1 23 V9 Q1 1 9 1 H21 Q29 1 29 9 V23 Z"/><text class="t" x="15" y="13">${label}</text></svg>`;
// パッドの右の 4 ボタン: 押す位置だけ塗る（機種で名前が違っても位置は同じ）
export const faceIcon = (pos: 'left' | 'down' | 'right' | 'up') => {
  const at = { up: [12, 4.5], right: [19.5, 12], down: [12, 19.5], left: [4.5, 12] } as const;
  return `<svg viewBox="0 0 24 24">${(Object.keys(at) as (keyof typeof at)[])
    .map((p) => `<circle class="${p === pos ? 'f' : 'o'}" cx="${at[p][0]}" cy="${at[p][1]}" r="3.6"/>`)
    .join('')}</svg>`;
};
export const CONTROL_ICONS: Record<ControlInput, [string, string]> = {
  attack: [mouseIcon('left'), triggerIcon('ZR')],
  aim: [mouseIcon('right'), triggerIcon('ZL')],
  reload: [keyIcon('R'), faceIcon('left')],
  wheel: [wheelIcon(), wheelIcon()],
  dash: [keyIcon('⇧'), keyIcon('L3')],
};
const controlsHud = document.getElementById('controls')!;
const focusKey = document.getElementById('focuskey')!; // 一閃・デッドアイのゲージの左のアイコン
const hookKey = document.getElementById('hookkey')!; // 鎖鎌のゲージの左のアイコン
let controlsHudKey = '';
export function updateControlsHud(shownWeapon: WeaponId, usingPad: boolean) {
  const key = `${shownWeapon}:${usingPad}`;
  if (key === controlsHudKey) return;
  const weaponChanged = !controlsHudKey.startsWith(`${shownWeapon}:`);
  controlsHudKey = key;
  const pad = usingPad ? 1 : 0;
  focusKey.innerHTML = hookKey.innerHTML = CONTROL_ICONS.aim[pad];
  controlsHud.innerHTML = WEAPON_CONTROLS[shownWeapon]
    .map(({ label, keys, padKeys }) => {
      const icons = (usingPad && padKeys ? padKeys : keys)
        .map((b) => `<span class="k">${CONTROL_ICONS[b.input][pad]}${b.hold ? '<small>HOLD</small>' : ''}</span>`)
        .join('<span class="plus">+</span>');
      return `<div class="row"><span class="label">${label}</span><span class="keys">${icons}</span></div>`;
    })
    .join('');
  if (!weaponChanged) return;
  restartAnim(controlsHud, 'in'); // 続けて持ち替えても頭から流し直す
}
