// ---- ゲームパッドの割り当て ----
// ボタンはキーに置き換えて keys / pressed に入れ、キーボードと同じ処理を通す

// 本体からも読み書きする値
export const padState = {
  fromPad: false, // パッドのボタンから送ったキー操作を処理している間だけ true
  padSprint: false,
};

export const PAD_KEYS: [number, string][] = [
  [PAD.A, 'Space'], // ジャンプ
  [PAD.B, 'KeyC'], // スライド
  [PAD.R3, 'KeyC'], // スライド
  [PAD.L3, 'ShiftLeft'], // ダッシュ
];
export const PAD_WEAPONS: [number, WeaponId][] = [
  [PAD.UP, 'kunai'],
  [PAD.RIGHT, 'handgun'],
  [PAD.DOWN, 'sword'],
  [PAD.LEFT, 'sickle'],
];
export const WEAPON_ORDER: WeaponId[] = ['kunai', 'handgun', 'sword', 'sickle', 'axe', 'bow', 'bat', 'spear', 'rifle']; // LB / RB で順に回す
// タイトル / 一時停止の画面では、メニューのキー操作に置き換える
export const PAD_MENU_KEYS: [number, string][] = [
  [PAD.B, 'Enter'],
  [PAD.START, 'Enter'],
  [PAD.A, 'Escape'],
  [PAD.Y, 'KeyQ'], // 一時停止からタイトルへ
  [PAD.BACK, 'KeyK'], // retry / return to lobby
  [PAD.X, 'KeyO'], // オプション
  [PAD.UP, 'ArrowUp'],
  [PAD.DOWN, 'ArrowDown'],
  [PAD.LEFT, 'ArrowLeft'],
  [PAD.RIGHT, 'ArrowRight'],
  [PAD.LB, 'PageUp'], // 武器の選択画面でカーソルを動かす
  [PAD.RB, 'PageDown'],
];
export const PAD_LOOK_SPEED = 4.2; // 右スティックを倒しきったときの視点の速さ (rad/s)
export const PAD_LOOK_VERTICAL = 0.75; // 縦方向の視点速度（横に対する倍率）
export const PAD_LOOK_CURVE = 1.6; // 小さく倒したときに細かく狙えるよう、倒した量を累乗して使う
export const PAD_LOOK_ACCEL_DELAY = 0.15; // 端に倒してから加速が始まるまでの秒数
export const PAD_LOOK_ACCEL_TIME = 0.3; // 最大倍率に達するまでの秒数
export const PAD_LOOK_ACCEL_MAX = 1.8; // 端に倒し続けたときの最大倍率
export const PAD_SPRINT = 0.9; // 左スティックをこれ以上倒すと走る

export function sendPadKey(code: string) {
  padState.fromPad = true;
  window.dispatchEvent(new KeyboardEvent('keydown', { code, cancelable: true }));
  padState.fromPad = false;
}

// 毎フレーム、ゲームの更新の前に呼ぶ（dt は実時間。視点の速さはスローの影響を受けない）
// パッドの遅れを調べる: ?pad で、入力が届く間隔とフレームの間隔を 1 秒ごとに左上へ出す
export const padDebug = new URLSearchParams(location.search).has('pad') ? document.createElement('div') : null;
if (padDebug) {
  padDebug.style.cssText =
    'position:fixed;left:12px;top:12px;z-index:100;padding:6px 10px;background:rgba(0,0,0,0.6);color:#fff;' +
    'font:13px/1.5 ui-monospace,Consolas,monospace;white-space:pre;pointer-events:none';
  document.body.appendChild(padDebug);
}
// エイムアシストの状態は毎フレーム書き換える
export const padAssistEl = padDebug ? document.createElement('div') : null;
if (padAssistEl) {
  padAssistEl.style.cssText = padDebug!.style.cssText.replace('top:12px', 'top:64px');
  document.body.appendChild(padAssistEl);
}
let padLastStamp = 0;
let padDebugT = 0;
let menuStickDirection = '';
let menuStickTimer = 0;
export const padGaps: number[] = [];
export const frameGaps: number[] = [];
export function updatePadDebug(dt: number, stamp: number) {
  if (!padDebug) return;
  frameGaps.push(dt * 1000);
  // 時刻が変わったときだけ新しい入力が届いている（スティックを動かしている間に見る）
  if (stamp && stamp !== padLastStamp) {
    if (padLastStamp) padGaps.push(stamp - padLastStamp);
    padLastStamp = stamp;
  }
  padDebugT += dt;
  if (padDebugT < 1) return;
  padDebugT = 0;
  const fmt = (a: number[]) =>
    a.length ? `平均 ${(a.reduce((s, v) => s + v, 0) / a.length).toFixed(1)} / 最大 ${Math.max(...a).toFixed(1)} ms` : '—';
  padDebug.textContent =
    `入力  ${fmt(padGaps)}  (${padGaps.length} 回/秒)\n` +
    `描画  ${fmt(frameGaps)}  (${frameGaps.length} fps, 50ms 超え ${frameGaps.filter((v) => v > 50).length})`;
  padGaps.length = frameGaps.length = 0;
}

let padThrowHeld = false;
let padLookEdgeTime = 0;
let trackedEnemy: Enemy | null = null;
let trackedYaw = 0;
let trackedPitch = 0;

export function updatePad(dt: number) {
  const pad = pollPad();
  updatePadDebug(dt, pad.timestamp);
  // 離したことはどの画面でも反映する（押したまま一時停止して、そこで離すこともある）
  for (const [b, code] of PAD_KEYS) {
    if (pad.up[b] && !PAD_KEYS.some(([other, key]) => key === code && pad.held[other])) keys.delete(code);
  }
  if (pad.up[PAD.RT]) game.attackHeld = false;
  if (pad.up[PAD.LT]) { game.throwHeld = false; padThrowHeld = false; }
  if (pad.up[PAD.LT]) { kunaiState.grappleHeld = false; if (kunaiState.grapple) releaseKunaiGrapple(); }
  padMove.x = padMove.y = 0;
  padState.padSprint = false;
  if (!pad.connected) { padLookEdgeTime = 0; trackedEnemy = null; if (padThrowHeld) game.throwHeld = padThrowHeld = false; clearLockOn(); return; }

  if (!controls.isLocked) {
    padLookEdgeTime = 0;
    trackedEnemy = null;
    clearLockOn();
    if (overlay.classList.contains('hidden') || overlay.classList.contains('leaving')) return;
    for (const [b, code] of PAD_MENU_KEYS) if (pad.down[b]) return sendPadKey(code);
    const direction = Math.max(Math.abs(pad.lx), Math.abs(pad.ly)) < 0.5 ? '' :
      Math.abs(pad.lx) > Math.abs(pad.ly) ? (pad.lx < 0 ? 'ArrowLeft' : 'ArrowRight') : (pad.ly < 0 ? 'ArrowUp' : 'ArrowDown');
    if (direction !== menuStickDirection) {
      menuStickDirection = direction;
      menuStickTimer = 0.4;
      if (direction) sendPadKey(direction);
    } else if (direction && (menuStickTimer -= dt) <= 0) {
      menuStickTimer = 0.12;
      sendPadKey(direction);
    }
    return;
  }
  menuStickDirection = '';
  if (pad.down[PAD.START]) { padLookEdgeTime = 0; return hooks.pauseGame(); }

  for (const [b, code] of PAD_KEYS) {
    if (!pad.down[b]) continue;
    keys.add(code);
    pressed.add(code);
  }
  if (!game.unarmed && pad.down[PAD.RT]) game.attackPressed = game.attackHeld = true;
  if (!game.unarmed && pad.down[PAD.LT]) {
    if (game.shownWeapon === 'kunai') { if (!kunaiState.grapple) { kunaiState.grappleHeld = true; toggleKunaiGrapple(); } }
    else game.throwHeld = padThrowHeld = sickleState.throwPressed = swordState.focusPressed = axeState.axeLaunchPressed = gunState.deadEyePressed = bowState.aimPressed = spearThrow.aimPressed = true;
  }
  if (!game.unarmed && (pad.down[PAD.X] || pad.down[PAD.Y])) {
    if (game.shownWeapon === 'kunai') recallKunai();
    else if (game.shownWeapon === 'handgun') gunState.reloadQueued = true;
    else if (game.shownWeapon === 'rifle') rifleState.reloadQueued = true;
  }
  const cycle = game.weaponLocked ? 0 : (pad.down[PAD.RB] ? 1 : 0) - (pad.down[PAD.LB] ? 1 : 0);
  if (cycle) game.wantWeapon = WEAPON_ORDER[(WEAPON_ORDER.indexOf(game.wantWeapon) + cycle + WEAPON_ORDER.length) % WEAPON_ORDER.length];
  for (const [b, id] of PAD_WEAPONS) if (pad.down[b] && !game.weaponLocked) game.wantWeapon = id;

  padMove.x = pad.lx;
  padMove.y = -pad.ly;
  padState.padSprint = Math.hypot(pad.lx, pad.ly) >= PAD_SPRINT;

  const m = Math.hypot(pad.rx, pad.ry);
  if (m > 0 || padState.padSprint || pad.lx || pad.ly || pad.down.some(Boolean)) game.usingPad = true;
  if (!game.unarmed && pad.down[PAD.RT] && game.shownWeapon !== 'kunai') assistMeleeAttack();
  const locking = updateLockOn(dt, m);
  padLookEdgeTime = !locking && !isDown() && m >= 0.95 ? padLookEdgeTime + dt : 0;
  const lookAccel = 1 + (PAD_LOOK_ACCEL_MAX - 1) * Math.min(1, Math.max(0, (padLookEdgeTime - PAD_LOOK_ACCEL_DELAY) / PAD_LOOK_ACCEL_TIME));
  const target = locking ? null : findAssistTarget();
  // 敵の近くでは視点を遅くし、スティックか体を動かしている間だけ照準を胸へ寄せる（止まっていると勝手には動かさない）
  let slow = 1;
  if (target) {
    const near = 1 - target.angle / target.size; // 範囲の端で 0、胸の真上で 1
    slow = 1 - (1 - ASSIST_SLOW) * Math.sqrt(near);
    const active = Math.min(1, Math.max(m, Math.hypot(pad.lx, pad.ly)));
    const enemy = target.enemy!;
    // 見た目のよろめきではなく敵の基準位置の移動を追う。
    const dx = enemy.root.position.x - camera.position.x;
    const dz = enemy.root.position.z - camera.position.z;
    const spineY = (enemy.spine.userData.origin as THREE.Vector3).y;
    const neckY = (enemy.neck.userData.origin as THREE.Vector3).y;
    const dy = enemy.root.position.y + THREE.MathUtils.lerp(spineY, neckY, ASSIST_CHEST) - camera.position.y;
    const yaw = Math.atan2(dx, -dz);
    const pitch = Math.atan2(dy, Math.hypot(dx, dz));
    if (trackedEnemy === enemy && active > 0) {
      const yawDelta = Math.atan2(Math.sin(yaw - trackedYaw), Math.cos(yaw - trackedYaw));
      const follow = 0.65 * active * near;
      turnView(THREE.MathUtils.clamp(yawDelta * follow, -1.5 * dt, 1.5 * dt),
        -THREE.MathUtils.clamp((pitch - trackedPitch) * follow, -1.5 * dt, 1.5 * dt));
    }
    trackedEnemy = enemy;
    trackedYaw = yaw;
    trackedPitch = pitch;
    // スティックを大きく倒せば補助から抜けやすい。ライフルの上下は頭を狙う操作を優先する。
    const pull = 1 - Math.exp(-ASSIST_PULL * active * (1 - 0.75 * Math.min(1, m) ** 2) * dt);
    if (pull > 0) turnView(target.yaw * pull, game.shownWeapon === 'rifle' ? 0 : -target.pitch * pull);
  } else trackedEnemy = null;
  if (padAssistEl) {
    padAssistEl.textContent = !game.usingPad
      ? 'アシスト  切（マウス操作中）'
      : !isAssistWeaponActive()
        ? 'アシスト  切（射撃・投げの構え以外）'
        : target
          ? `アシスト  ● 捕捉中  ずれ ${(target.angle / DEG).toFixed(1)}° / 範囲 ${(target.size / DEG).toFixed(1)}°  速さ ×${slow.toFixed(2)}${game.shownWeapon !== 'rifle' && target.angle < target.size * ASSIST_SNAP ? '  弾補正' : ''}`
          : 'アシスト  ○ 範囲外';
  }
  if (m > 0) {
    const k = (Math.pow(m, PAD_LOOK_CURVE) / m) * PAD_LOOK_SPEED * options.padSens * dt * zoomLookScale() * slow * lookAccel;
    turnView(pad.rx * k, pad.ry * k * PAD_LOOK_VERTICAL);
    // マウスと同じく、回した量の 1/4 だけ武器を遅らせる
    viewState.lookSwayX = THREE.MathUtils.clamp(viewState.lookSwayX + pad.rx * k * 0.25, -0.06, 0.06);
    viewState.lookSwayY = THREE.MathUtils.clamp(viewState.lookSwayY + pad.ry * k * PAD_LOOK_VERTICAL * 0.25, -0.06, 0.06);
  }
}
